namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string CustomerEmail { get; set; } = string.Empty;
}

public class ShipmentTrackingResult
{
    public bool Found { get; set; }
    public ShipmentDto? Shipment { get; set; }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => new ShipmentDto
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status,
                CreatedAt = s.CreatedAt,
                EstimatedDelivery = s.EstimatedDelivery,
                RecipientName = s.RecipientName,
                CustomerEmail = s.CustomerEmail
            })
            .ToListAsync();
    }

    public async Task<ShipmentTrackingResult> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .Where(s => s.TrackingNumber == trackingNumber)
            .Select(s => new ShipmentDto
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status,
                CreatedAt = s.CreatedAt,
                EstimatedDelivery = s.EstimatedDelivery,
                RecipientName = s.RecipientName,
                CustomerEmail = s.CustomerEmail
            })
            .FirstOrDefaultAsync();

        return new ShipmentTrackingResult
        {
            Found = shipment is not null,
            Shipment = shipment
        };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var entity = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = dto.Status,
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            RecipientName = dto.RecipientName,
            CustomerEmail = dto.CustomerEmail
        };

        db.Shipments.Add(entity);
        await db.SaveChangesAsync();

        dto.Id = entity.Id;
        dto.CreatedAt = entity.CreatedAt;
        return dto;
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = newStatus;
            await db.SaveChangesAsync();
        }
    }
}

