@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Shipment Dashboard</h2>

<div class="mb-3">
    <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
            </div>
            <div class="row g-2 mt-2">
                <div class="col-md-3">
                    <label class="form-label">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="estimatedDelivery" />
                </div>
                <div class="col-md-3 d-flex align-items-end">
                    <button class="btn btn-primary me-2" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-outline-secondary" @onclick="CancelCreate">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found. Create one to get started.</div>
}
else
{
    <div class="mb-3">
        <input class="form-control" style="max-width:300px" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.RecipientName</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width:auto"
                                    value="@((int)shipment.Status)"
                                    @onchange="e => UpdateStatus(shipment, e)">
                                @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@((int)status)">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private bool showCreateForm;
    private string filterText = string.Empty;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDelivery;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments
            : shipments.Where(s => s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newShipment = new();
        estimatedDelivery = null;
    }

    private async Task CreateShipment()
    {
        newShipment.EstimatedDelivery = estimatedDelivery;
        newShipment.Status = ShipmentStatus.Pending;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments.Insert(0, created);
        CancelCreate();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g., SHP-20260612-A1B2C3D4)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                    <span> Searching...</span>
                }
                else
                {
                    <span>Track</span>
                }
            </button>
        </div>
    </div>
</div>

@if (searched && result is not null)
{
    @if (result.Found && result.Shipment is not null)
    {
        var s = result.Shipment;
        <div class="card mt-4" style="max-width: 600px">
            <div class="card-header">
                <strong>Tracking #:</strong> @s.TrackingNumber
            </div>
            <div class="card-body">
                <div class="row mb-2">
                    <div class="col-sm-4 fw-bold">Status:</div>
                    <div class="col-sm-8">
                        <span class="badge @GetStatusBadgeClass(s.Status) fs-6">@s.Status</span>
                    </div>
                </div>
                <div class="row mb-2">
                    <div class="col-sm-4 fw-bold">Origin:</div>
                    <div class="col-sm-8">@s.Origin</div>
                </div>
                <div class="row mb-2">
                    <div class="col-sm-4 fw-bold">Destination:</div>
                    <div class="col-sm-8">@s.Destination</div>
                </div>
                <div class="row mb-2">
                    <div class="col-sm-4 fw-bold">Recipient:</div>
                    <div class="col-sm-8">@s.RecipientName</div>
                </div>
                <div class="row mb-2">
                    <div class="col-sm-4 fw-bold">Shipped On:</div>
                    <div class="col-sm-8">@s.CreatedAt.ToString("MMMM dd, yyyy")</div>
                </div>
                @if (s.EstimatedDelivery.HasValue)
                {
                    <div class="row mb-2">
                        <div class="col-sm-4 fw-bold">Estimated Delivery:</div>
                        <div class="col-sm-8">
                            <span class="text-success fw-bold">@s.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</span>
                        </div>
                    </div>
                }
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning mt-4" style="max-width: 600px">
            No shipment found with tracking number "<strong>@searchedNumber</strong>". Please verify and try again.
        </div>
    }
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private bool searching;
    private bool searched;
    private ShipmentTrackingResult? result;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        searched = false;
        searchedNumber = trackingNumber.Trim();
        result = await ShipmentService.TrackShipmentAsync(searchedNumber);
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

